export const SKILLS=grades.map((list,grade)=>list.map(([kind,label,code,world],i)=>({id:`${grade}-${kind}`,grade,kind,label,code:code==='Extension'?code:'NC.'+code,world,index:i})));
for(const [grade,list]of ADDITIONAL_SKILLS.entries())for(const [kind,label,code,world]of list)SKILLS[grade].push({id:`${grade}-${kind}`,grade,kind,label,code:'NC.'+code,world,index:SKILLS[grade].length});
// Fact families are available for deliberate practice and tracked alongside mixed multiplication.
SKILLS[3].push(...Array.from({length:8},(_,i)=>({id:`3-times-${i+2}`,grade:3,kind:'multiply',label:`${i+2} times table`,code:'NC.3.OA.7',world:2,index:SKILLS[3].length+i,factor:i+2,practiceOnly:true})));
export const gradeLabel=g=>g===0?'Kindergarten':`Grade ${g}`;
export const skillById=id=>SKILLS.flat().find(s=>s.id===id);
export function freshMath(){return {version:1,grade:0,skills:{},answered:0,correct:0,wrong:0,bestScore:0,stars:0,worlds:{},tutorial:false,settings:{difficulty:'Adaptive',mode:'adventure',count:10,timer:true}};}

export const MATH_SUBJECTS=['Number & place value','Operations & problem solving','Fractions & decimals','Measurement & time','Geometry','Ratios & percentages','Algebra & patterns','Data & probability','Extra practice'];
export function mathSubject(skill){const code=skill.code;if(code==='Extension')return 'Extra practice';if(/SP\./.test(code)||/data|graph|sort|statistics|scatter|compareCenter|lineGraph/i.test(skill.kind))return 'Data & probability';if(/RP\./.test(code))return 'Ratios & percentages';if(/NF\./.test(code)||/fraction|decimal|partition|halfQuarter|mixedMultiply/i.test(skill.kind))return 'Fractions & decimals';if(/\.G\./.test(code)||/^(area|perimeter|angle|volume|rectilinearArea)/.test(skill.kind))return 'Geometry';if(/MD\./.test(code))return 'Measurement & time';if(/EE\.|\.F\./.test(code)||/pattern/i.test(skill.kind))return 'Algebra & patterns';if(/OA\./.test(code))return 'Operations & problem solving';return 'Number & place value';}
export function gradeSubjects(grade){return MATH_SUBJECTS.filter(name=>SKILLS[grade].some(s=>mathSubject(s)===name));}
